--Q1. What is the total revenue generated by male vs. female 
SELECT
	GENDER,
	SUM(PURCHASE_AMOUNT) AS REVENUE_OF_MALE_OR_FEMALE
FROM
	CUSTOMER
GROUP BY
	GENDER
ORDER BY
	REVENUE_OF_MALE_OR_FEMALE DESC
--Q2. Which customers used a discount but still spent more than the average purchase amount?  
SELECT
	*
FROM
	CUSTOMER
WHERE
	DISCOUNT_APPLIED = 'Yes'
	AND PURCHASE_AMOUNT >= (
		SELECT
			AVG(PURCHASE_AMOUNT)
		FROM
			CUSTOMER
	)
--Q3. Which are the top 5 products with the highest average review rating?
SELECT
	ITEM_PURCHASED,
	ROUND(AVG(REVIEW_RATING::NUMERIC), 2) AS AVG_RATING
FROM
	CUSTOMER
GROUP BY
	ITEM_PURCHASED
ORDER BY
	AVG_RATING DESC
LIMIT
	5

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
SELECT
	SHIPPING_TYPE,
	ROUND(AVG(PURCHASE_AMOUNT), 2) AS AVG_PURCHASES
FROM
	CUSTOMER
WHERE
	SHIPPING_TYPE IN ('Express', 'Standard')
GROUP BY
	SHIPPING_TYPE

--Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
SELECT
	SUBSCRIPTION_STATUS,
	count(*) as total_customer,
	SUM(PURCHASE_AMOUNT) AS REVENUE,
	ROUND(AVG(PURCHASE_AMOUNT), 2) AS AVG_REVENUE
FROM
	CUSTOMER
GROUP BY
	SUBSCRIPTION_STATUS
	order by REVENUE desc

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT
	ITEM_PURCHASED,
	ROUND(
		100.0 * SUM(
			CASE
				WHEN DISCOUNT_APPLIED = 'Yes' THEN 1
				ELSE 0
			END
		) / COUNT(*),
		2
	) AS PCT_OF_PURCHASED
FROM
	CUSTOMER
GROUP BY
	ITEM_PURCHASED
ORDER BY
	PCT_OF_PURCHASED DESC
LIMIT
	5
	
--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 
WITH
	CET AS (
		SELECT
			CASE
				WHEN PREVIOUS_PURCHASES = 1 THEN 'New'
				WHEN PREVIOUS_PURCHASES BETWEEN 2 AND 10  THEN 'Returning'
				ELSE 'Loyal'
			END AS CUSTOMER_SEGMENT
		FROM
			CUSTOMER
	)
SELECT
	CUSTOMER_SEGMENT,
	COUNT(*) AS TOTAL_CUSTOMER
FROM
	CET
GROUP BY
	CUSTOMER_SEGMENT
ORDER BY
	TOTAL_CUSTOMER DESC
	
--Q8. What are the top 3 most purchased products within each category? 
select * from (
		SELECT
			CATEGORY,
			ITEM_PURCHASED,
			count(customer_id) as total_orders,
			row_number () OVER (PARTITION BY CATEGORY ORDER BY count(customer_id) DESC) AS RANKING
		FROM
			CUSTOMER
		GROUP BY
			CATEGORY,
			ITEM_PURCHASED
	)
WHERE
	RANKING <= 3

--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT
	SUBSCRIPTION_STATUS,
	COUNT(CUSTOMER_ID) AS REPEAT_BUYERS
FROM
	CUSTOMER
WHERE
	PREVIOUS_PURCHASES > 5
GROUP BY
	SUBSCRIPTION_STATUS;
	
--Q10. What is the revenue contribution of each age group?
SELECT 
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue desc;